import { BASE_URL, getDefaultHeaders, } from '../shared/constants/url.constants';
import { cloneDeep } from 'lodash-es';
import * as i0 from "@angular/core";
import * as i1 from "@angular/common/http";
import * as i2 from "./booking.service";
import * as i3 from "src/app/services/bookingid.service";
export class PaymentService {
    constructor(http, bookingService, BookingConfigService) {
        this.http = http;
        this.bookingService = bookingService;
        this.BookingConfigService = BookingConfigService;
    }
    async createOrderAndMakePayment(bookingItem, personalDetailsForm, payathotel) {
        console.log(bookingItem, personalDetailsForm, payathotel, "!!!!!");
        this.createOrder(bookingItem).subscribe((res1) => {
            this.makePayment(bookingItem, personalDetailsForm, payathotel);
        });
    }
    createOrder(bookingItem) {
        let params = {
            bookingEngineId: this.BookingConfigService.getBookingEngineId(),
            productId: bookingItem.hotelId,
            searchId: bookingItem.searchId,
            checkIn: bookingItem.checkIn,
            checkOut: bookingItem.checkOut,
            cityId: bookingItem.renderData.address.cityId,
            paxInfo: bookingItem.paxInfo,
            selectedrooms: `{"1":{"productId":${bookingItem.hotelId},"roomMap":{"0":{"roomId":${bookingItem.rooms[0].roomId},"ratePlanId":${bookingItem.rooms[0].ratePlanId},"addOnMap":{},"addchildMap":{},"policyChargeScope":{}}}}}`,
        };
        return this.http.get(`${BASE_URL}api/be/rooms`, {
            params: params,
            headers: getDefaultHeaders(),
        });
    }
    makePayment(bookingItem, personalDetails, payathotel) {
        this.bookingService.setPGLoaderFlag();
        const item = cloneDeep(bookingItem);
        const postpayment = personalDetails.prepayment ? item.totalAmount - personalDetails.prepayment : 0;
        // normalize some fields
        const firstName = personalDetails.firstName || '';
        const lastName = personalDetails.lastName || '';
        const email = personalDetails.emailId || '';
        const mobile = personalDetails.mobileNo || '';
        const guestAddress = personalDetails.address || personalDetails.guest_address || '';
        const additionalRequest = personalDetails.specialRequest || '';
        // derive pay-at-hotel flags (include both variants to be safe)
        const payAtHotelWithCC = !!payathotel ? 'true' : 'false';
        const payAtHotelWithoutCC = !!payathotel ? 'false' : 'true';
        const params = {
            isBEV3: 'true',
            searchId: item.searchId || '',
            currency: '1',
            promoCodeApplied: '',
            promoCode: '',
            guestORlogin: 'guestform',
            master_pax_first_name: firstName,
            master_pax_last_name: lastName,
            contactEmail: email,
            contactMobile: mobile,
            guest_address: guestAddress,
            additional_request: additionalRequest,
            acceptTerms: 'on',
            payAtHotelWithoutCC,
            cardType: '',
            cardNO: '',
            cardValidity_month: '',
            cardValidity_year: '',
            cardHolderName: '',
            cardValidity_cvv: '',
            AgodacardType: '',
            AgodacardNO: '',
            AgodacardValidity_month: '',
            AgodacardValidity_year: '',
            AgodacardValidity_cvv: '',
            AgodacardHolderName: '',
            postAmountValue: String(postpayment || 0),
        };
        const qs = Object.entries(params)
            .map(([k, v]) => `${k}=${encodeURIComponent(v)}`)
            .join('&');
        const finalUrl = `https://app.axisrooms.com/beV2/hotelBooking.html?${qs}`;
        window.open(finalUrl, '_self');
    }
}
